questionvariables.text:
/* exd: shortest exact decimal display of a terminating value (up to 3 d.p.) */
exd(v) := if integerp(v) then v else if integerp(10*v) then dispdp(float(v),1) else if integerp(100*v) then dispdp(float(v),2) else dispdp(float(v),3);
/* Design: find-the-mistake pattern. er 1: step 3 uses sum of (fx)^2; er 2: step 5 subtracts x-bar, not x-bar^2; er 3: step 6 gives the variance as sigma. Source: original. */
xs: [10,15,20,25,30];
flist: [[3,10,10,12,1],[2,8,12,5,3],[1,10,8,6,3],[6,6,10,4,1],[2,2,9,11,12],[3,5,8,4,1],[2,2,9,7,1],[4,7,11,3,2],[4,7,5,5,1],[1,8,11,4,2]];
ix: 1+rand(10);
f: flist[ix];
er: rand([1,2,3]);
n: apply("+",f);
Sfx: sum(f[k]*xs[k],k,1,5);
Sfx2: sum(f[k]*xs[k]^2,k,1,5);
mn: Sfx/n;
vr: Sfx2/n-mn^2;
sdv: sqrt(vr);
Sfx2s: if er=1 then sum((f[k]*xs[k])^2,k,1,5) else Sfx2;
sq5: if er=2 then mn else mn^2;
v5: Sfx2s/n-sq5;
sd6: if er=3 then v5 else sqrt(v5);
mnr: floor(1000*mn+1/2)/1000;
mnd: if is(mn=mnr) then exd(mn) else dispdp(float(mnr),3);
sq5d: dispdp(float(floor(10^3*(sq5)+1/2)/10^3),3);
v5d: dispdp(float(floor(10^3*(v5)+1/2)/10^3),3);
sd6d: dispdp(float(floor(10^2*(sd6)+1/2)/10^2),2);
sdd: dispdp(float(floor(10^2*(sdv)+1/2)/10^2),2);
vrd: dispdp(float(floor(10^3*(vr)+1/2)/10^3),3);
sqd: dispdp(float(floor(10^3*(mn^2)+1/2)/10^3),3);
opts: [["s1",false,"Step 1"],["s2",false,"Step 2"],["s3",is(er=1),"Step 3"],["s4",false,"Step 4"],["s5",is(er=2),"Step 5"],["s6",is(er=3),"Step 6"]];
wr1: if er=1 then "s5" else "s3";
sdn1: sqrt(Sfx2/(n-1)-mn^2*n/(n-1));
/* test values */
sd2: float(floor(10^2*(sdv)+1/2)/10^2);
sd62: float(floor(10^2*(sd6)+1/2)/10^2);
sdn12: float(floor(10^2*(sdn1)+1/2)/10^2);
